import OSLog

// Logger is Sendable; nonisolated keeps these properties callable from service actors.
extension Logger {
    nonisolated static let server     = Logger(subsystem: "app.maekster.server",     category: "ServerService")
    nonisolated static let player     = Logger(subsystem: "app.maekster.player",     category: "PlayerService")
    nonisolated static let library    = Logger(subsystem: "app.maekster.library",    category: "LibraryService")
    nonisolated static let cache      = Logger(subsystem: "app.maekster.cache",      category: "AudioStreamCache")
    nonisolated static let download   = Logger(subsystem: "app.maekster.download",   category: "DownloadService")
    nonisolated static let resolver   = Logger(subsystem: "app.maekster.resolver",   category: "MediaResolver")
    nonisolated static let nowPlaying = Logger(subsystem: "app.maekster.nowplaying", category: "NowPlayingService")
    nonisolated static let keychain   = Logger(subsystem: "app.maekster.keychain",   category: "KeychainService")
    nonisolated static let network     = Logger(subsystem: "app.maekster.network",    category: "NetworkMonitor")
    nonisolated static let ui         = Logger(subsystem: "app.maekster.ui",         category: "UI")
    nonisolated static let favorites   = Logger(subsystem: "app.maekster.favorites",  category: "FavoritesService")
    nonisolated static let pin         = Logger(subsystem: "app.maekster.pin",        category: "PinService")
    nonisolated static let session     = Logger(subsystem: "app.maekster.session",    category: "PlaybackSessionService")
    nonisolated static let playlist    = Logger(subsystem: "app.maekster.playlist",   category: "PlaylistService")
    nonisolated static let radio       = Logger(subsystem: "app.maekster.radio",      category: "RadioService")
    nonisolated static let discover      = Logger(subsystem: "app.maekster.discover",      category: "DiscoverViewModel")
    nonisolated static let dominantColor = Logger(subsystem: "app.maekster.dominantColor", category: "DominantColorExtractor")
    nonisolated static let stats         = Logger(subsystem: "app.maekster.stats",         category: "StatsService")
    nonisolated static let wrapped       = Logger(subsystem: "app.maekster.wrapped",       category: "WrappedPlaylistService")
    nonisolated static let wrappedStory  = Logger(subsystem: "app.maekster.wrappedstory",  category: "WrappedStoryPlayer")
    nonisolated static let lyrics        = Logger(subsystem: "app.maekster.lyrics",        category: "LyricsService")
    nonisolated static let moodPlaylists = Logger(subsystem: "app.maekster.moodplaylists", category: "MoodPlaylistService")
    nonisolated static let recommendations  = Logger(subsystem: "app.maekster.recommendations",  category: "RecommendationService")
    nonisolated static let listenBrainz     = Logger(subsystem: "app.maekster.listenbrainz",     category: "ListenBrainz")
    nonisolated static let integrations       = Logger(subsystem: "app.maekster.integrations",       category: "Integrations")
    nonisolated static let externalArtwork    = Logger(subsystem: "app.maekster.externalartwork",    category: "ExternalArtworkCache")
    nonisolated static let artistArtwork      = Logger(subsystem: "app.maekster.artistartwork",      category: "ExternalArtistImageResolver")
    nonisolated static let httpTransport      = Logger(subsystem: "app.maekster.transport",          category: "CustomHeadersTransport")
    nonisolated static let artworkCache       = Logger(subsystem: "app.maekster.artworkcache",       category: "ArtworkCache")
    nonisolated static let boot               = Logger(subsystem: "app.maekster.boot",               category: "Boot")
    nonisolated static let migration          = Logger(subsystem: "app.maekster.migration",          category: "Migration")
}
